'use strict';

var _objectSpread = require('@babel/runtime/helpers/objectSpread2');
var httpHelpers = require('@toruslabs/http-helpers');
var Bowser = require('bowser');
var log = require('loglevel');

const SIWW_CONFIG = {
  solana: {
    type: "sip99",
    network: "solana"
  },
  eip155: {
    type: "eip191",
    network: "ethereum"
  }
};
const DEFAULT_SIWW = SIWW_CONFIG.eip155;
function getDeviceInfo() {
  if (typeof navigator === "undefined" || !navigator.userAgent) {
    return {
      platform: "unknown",
      os: "unknown",
      osVersion: "0",
      browser: "unknown",
      browserVersion: "0"
    };
  }
  const parsed = Bowser.parse(navigator.userAgent);
  const {
    browser: b,
    os: o,
    platform: p
  } = parsed;
  return {
    platform: p.type || "unknown",
    os: o.name || "unknown",
    osVersion: o.version || "0",
    browser: b.name || "unknown",
    browserVersion: b.version || "0"
  };
}
const signChallenge = async (payload, chainNamespace, authServer) => {
  const {
    type,
    network
  } = SIWW_CONFIG[chainNamespace] || DEFAULT_SIWW;
  const data = {
    payload,
    header: {
      t: type
    },
    network
  };
  const res = await httpHelpers.post(`${authServer}/v1/siww/challenge`, data);
  if (!res.success) {
    throw new Error("Failed to authenticate user, Please reach out to Web3Auth Support team");
  }
  return res.challenge;
};
const verifySignedChallenge = async params => {
  const {
    chainNamespace,
    signedMessage,
    challenge,
    connector,
    authServer,
    web3AuthClientId,
    web3AuthNetwork,
    sessionTimeout,
    deviceInfo,
    sessionNamespace
  } = params;
  const {
    type
  } = SIWW_CONFIG[chainNamespace] || DEFAULT_SIWW;
  const body = _objectSpread({
    signature: {
      s: signedMessage,
      t: type
    },
    message: challenge,
    web3AuthClientId,
    web3AuthNetwork,
    connector,
    sessionTimeout,
    deviceInfo
  }, sessionNamespace != null ? {
    sessionNamespace
  } : {});
  const res = await httpHelpers.post(`${authServer}/v1/siww/verify`, body);
  if (!res.success) {
    log.error("Failed to authenticate user, message verification failed", res.error);
    throw new Error("Failed to authenticate user, message verification failed");
  }
  return {
    idToken: res.id_token,
    accessToken: res.access_token,
    refreshToken: res.refresh_token
  };
};

exports.getDeviceInfo = getDeviceInfo;
exports.signChallenge = signChallenge;
exports.verifySignedChallenge = verifySignedChallenge;
